            node.LeftChild = InsertHelper(node.LeftChild, value);
        }
        else
        {
            node.RightChild = InsertHelper(node.RightChild, value);
        }

        // Update height of the node
        node.Height = 1 + Math.Max(GetHeight(node.LeftChild), GetHeight(node.RightChild));

        // Check if the node is balanced and rebalance if needed
        int balanceFactor = GetBalanceFactor(node);

