        {
            node.LeftChild = RotateLeft(node.LeftChild);
            return RotateRight(node);
        }

        if (balanceFactor < -1 && value.CompareTo(node.RightChild.Value) > 0)
        {
            return RotateLeft(node);
        }

        if (balanceFactor < -1 && value.CompareTo(node.RightChild.Value) < 0)
