Here is the sample code for building a Ktor server that allows authenticated users to search for and retrieve data from a MongoDB database containing information about books:

```
// Import required libraries
import io.ktor.application.*
import io.ktor.auth.*
import io.ktor.features.*
import io.ktor.http.*
import io.ktor.response.*
import io.ktor.routing.*
import io.ktor.serialization.*
import io.ktor.util.*
import kotlinx.serialization.json.*
import org.litote.kmongo.*

// Define database and collection
val client = KMongo.createClient()
val database = client.getDatabase("mydb")
val bookCollection = database.getCollection<Book>("books")

// Define data model
@Serializable
data class Book(
    val title: String,
    val author: String,
    val year: Int,
    val isbn: String
)

// Define authentication realm
const val REALM = "booksearch"

// Define API routes
fun Routing.bookSearch() {
    authenticate(REALM) {
        get("/books") {
            val title = call.parameters["title"]
            val author = call.parameters["author"]
            val year = call.parameters["year"]?.toIntOrNull()
            val isbn = call.parameters["isbn"]
            val pageSize = call.parameters["pageSize"]?.toIntOrNull() ?: 10
            val pageNumber = call.parameters["pageNumber"]?.toIntOrNull() ?: 1
            val sortBy = call.parameters["sortBy"] ?: "title"
            val sortOrder = call.parameters["sortOrder"] ?: "asc"

            val query = bookCollection.createQuery()
            if (title != null) query.and("title" equal title)
            if (author != null) query.and("author" equal author)
            if (year != null) query.and("year" equal year)
            if (isbn != null) query.and("isbn" equal isbn)

            val books = query
                .sort("{ $sortBy: ${if (sortOrder == "asc") 1 else -1} }")
                .skip((pageNumber - 1) * pageSize).limit(pageSize)
                .toList()

            val totalBooks = bookCollection.countDocuments(query)
            val totalPages = (totalBooks + pageSize - 1) / pageSize

            call.respond(mapOf(
                "books" to Json.encodeToString(books),
                "totalBooks" to totalBooks,
                "totalPages" to totalPages,
                "pageSize" to pageSize,
                "pageNumber" to pageNumber,
                "sortBy" to sortBy,
                "sortOrder" to sortOrder
            ))
        }
    }
}

// Define authentication provider
fun Application.formBasedAuthentication() {
    install(Authentication) {
        form("auth") {
            userParamName = "username"
            passwordParamName = "password"
            challenge = FormAuthChallenge.Unauthorized
            validate { credentials ->
                if (credentials.name == "admin" && credentials.password == "password") UserIdPrincipal(credentials.name) else null
            }
        }
    }
}

// Define error handling
fun Application.errorHandling() {
    install(DefaultHeaders)
    install(CallLogging)
    install(StatusPages) {
        exception<Throwable> { cause ->
            call.respond(HttpStatusCode.InternalServerError)
            throw cause
        }
    }
}

// Define serialization
fun Application.jsonSerialization() {
    install(ContentNegotiation) {
        json(Json {
            prettyPrint = true
            isLenient = true
            ignoreUnknownKeys = true
        })
    }
}

// Define server configuration
fun Application.module() {
    formBasedAuthentication()
    errorHandling()
    jsonSerialization()

    routing {
        bookSearch()
    }
}

// Start server
fun main() {
    embeddedServer(Netty, port = 8080, module = Application::module).start(wait = true)
}
```

This code defines a Ktor server that provides a RESTful API for searching and retrieving books from a MongoDB database. 

The `Book` data model is defined using Kotlin Serialization, and the `bookSearch` route uses query parameters to allow filtering, sorting, and pagination of books. The route is protected by form-based authentication, and error handling is accomplished using Ktor's `StatusPages` feature. Finally, the server is configured for JSON serialization using Kotlin Serialization.

To start the server, run the `main` function. The server will listen on port 8080. To perform a book search, send an authenticated GET request to `/books` with the desired query parameters. The response will be a JSON object containing the requested books, as well as metadata about the search results.

