    {
        private Dictionary<T, List<T>> adjList;
        private bool isDirected;

        public Graph(bool isDirected = false)
        {
            this.adjList = new Dictionary<T, List<T>>();
            this.isDirected = isDirected;
        }

        public void AddVertex(T vertex)
        {
            if (!adjList.ContainsKey(vertex))
            {
                adjList[vertex] = new List<T>();
            }
        }

        public void AddEdge(T fromVertex, T toVertex)
        {
            if (!adjList.ContainsKey(fromVertex))
            {
                adjList[fromVertex] = new List<T>();
            }
            if (!adjList.ContainsKey(toVertex))
            {
                adjList[toVertex] = new List<T>();
            }
            adjList[fromVertex].Add(toVertex);
            if (!isDirected)
            {
                adjList[toVertex].Add(fromVertex);
            }
        }

        public void RemoveVertex(T vertex)
        {
            if (adjList.ContainsKey(vertex))
            {
                adjList.Remove(vertex);
                foreach (var adjVertices in adjList.Values)
                {
                    adjVertices.Remove(vertex);
                }
            }
        }

        public void RemoveEdge(T fromVertex, T toVertex)
        {
            if (adjList.ContainsKey(fromVertex) && adjList.ContainsKey(toVertex))
            {
                adjList[fromVertex].Remove(toVertex);
                if (!isDirected)
                {
                    adjList[toVertex].Remove(fromVertex);
                }
            }
        }

        public bool IsConnected(T fromVertex, T toVertex)
        {
            if (!adjList.ContainsKey(fromVertex) || !adjList.ContainsKey(toVertex))
            {
                return false;
            }
            var visited = new HashSet<T>();
            var queue = new Queue<T>();
            queue.Enqueue(fromVertex);
            while (queue.Count > 0)
            {
                var currVertex = queue.Dequeue();
                if (currVertex.Equals(toVertex))
                {
                    return true;
                }
                visited.Add(currVertex);
                foreach (var adjVertex in adjList[currVertex])
                {
                    if (!visited.Contains(adjVertex))
                    {
                        queue.Enqueue(adjVertex);
                    }
                }
            }
            return false;
        }

        public IEnumerable<T> DFS(T startVertex)
        {
            var visited = new HashSet<T>();
            var stack = new Stack<T>();
            visited.Add(startVertex);
            stack.Push(startVertex);
            while (stack.Count > 0)
            {
                var currVertex = stack.Pop();
                yield return currVertex;
                foreach (var adjVertex in adjList[currVertex])
                {
                    if (!visited.Contains(adjVertex))
                    {
                        visited.Add(adjVertex);
                        stack.Push(adjVertex);
                    }
                }
            }
        }

        public IEnumerable<T> BFS(T startVertex)
        {
            var visited = new HashSet<T>();
            var queue = new Queue<T>();
            visited.Add(startVertex);
            queue.Enqueue(startVertex);
            while (queue.Count > 0)
            {
                var currVertex = queue.Dequeue();
                yield return currVertex;
                foreach (var adjVertex in adjList[currVertex])
                {
                    if (!visited.Contains(adjVertex))
                    {
                        visited.Add(adjVertex);
                        queue.Enqueue(adjVertex);
                    }
                }
            }
